  "2019 P1 Q7": {"v":"change-subject.fraction-coefficient-bracket","marks":[1,1,1],"shows":["\\(2A = h(x + y)\\)","\\(\\frac{2A}{h} = x + y\\) OR \\(2A - hy = hx\\)",null],"marksLine":"3 marks","nudge":"What has been done to \\(x\\) on the right, and in what order? Undo it in reverse.","step":"Multiply both sides by \\(2\\) to clear the \\(\\frac{1}{2}\\).","watch":"Divide by \\(h\\) before you take away \\(y\\): the \\(h\\) multiplies the whole bracket."},
