  "2025 P1 Q12": {"v":"surds.rationalise","marks":[1,1],"shows":["\\(\\frac{6\\sqrt{10}}{10}\\)",null],"marksLine":"2 marks","nudge":"What can you multiply the top and bottom by to get rid of \\(\\sqrt{10}\\) on the bottom?","step":"Multiply the top and the bottom by \\(\\sqrt{10}\\): \\(\\sqrt{10} \\times \\sqrt{10}\\) is a whole number.","watch":"Simplify at the end: the whole numbers top and bottom have a common factor."},
