  "2025 P2 Q14": {"v":"trig-equations.in-formula","marks":[1,1,1,1],"shows":["\\(13 = 10 - 8 \\cos x\\)","\\(\\cos x = -\\frac{3}{8}\\)","\\(112(.024...)\\)",null],"marksLine":"4 marks","nudge":"Height 13 m gives you an equation to solve. How do you get \\(\\cos x^\\circ\\) on its own?","step":"Put \\(h = 13\\) into \\(h = 10 - 8\\cos x^\\circ\\).","watch":"\\(\\cos x^\\circ\\) comes out negative, so the two angles are in the second and third quadrants."},
